import{_ as i,o as n,c as e,a3 as l}from"./chunks/framework.BvvarXmc.js";const d=JSON.parse('{"title":"Input Buku Nilai & Rekap Rapor","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-guru/rapor-nilai.md","filePath":"panduan-guru/rapor-nilai.md","lastUpdated":null}'),r={name:"panduan-guru/rapor-nilai.md"};function t(o,a,u,p,s,k){return n(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="input-buku-nilai-rekap-rapor" tabindex="-1">Input Buku Nilai &amp; Rekap Rapor <a class="header-anchor" href="#input-buku-nilai-rekap-rapor" aria-label="Permalink to &quot;Input Buku Nilai &amp; Rekap Rapor&quot;">​</a></h1><p>Buku Nilai (Gradebook) menyatukan seluruh komponen penilaian: nilai harian, nilai tugas LMS, nilai ujian CBT, serta penilaian sikap siswa.</p><hr><h2 id="_1-mengisi-nilai-mata-pelajaran" tabindex="-1">1. Mengisi Nilai Mata Pelajaran <a class="header-anchor" href="#_1-mengisi-nilai-mata-pelajaran" aria-label="Permalink to &quot;1. Mengisi Nilai Mata Pelajaran&quot;">​</a></h2><ol><li>Masuk ke menu <strong>Akademik</strong> <strong>Buku Nilai (Gradebook)</strong>.</li><li>Pilih mata pelajaran dan kelas yang Anda ampu.</li><li>Anda akan melihat kolom-kolom komponen nilai: <ul><li>Nilai Tugas 1, 2, 3...</li><li>Nilai Ulangan Harian (UH)</li><li>Nilai Ujian Tengah Semester (UTS / PTS)</li><li>Nilai Ujian Akhir Semester (UAS / PAS)</li></ul></li><li><em>Nilai dari tugas LMS dan ujian CBT dapat ditarik otomatis tanpa perlu mengetik ulang</em> dengan mengklik tombol <strong>Tarik Nilai Otomatis dari CBT/LMS</strong>.</li><li>Untuk input manual, cukup ketikkan angka di kolom yang bersangkutan.</li><li>Klik <strong>Simpan Nilai</strong>.</li></ol><hr><h2 id="_2-bobot-penilaian-nilai-akhir" tabindex="-1">2. Bobot Penilaian &amp; Nilai Akhir <a class="header-anchor" href="#_2-bobot-penilaian-nilai-akhir" aria-label="Permalink to &quot;2. Bobot Penilaian &amp; Nilai Akhir&quot;">​</a></h2><p>Sistem akan secara otomatis menghitung nilai akhir berdasarkan bobot yang ditetapkan kurikulum sekolah (contoh: 30% Tugas + 30% PTS + 40% PAS).</p><p>Jika nilai akhir di bawah batas Kriteria Ketercapaian Tujuan Pembelajaran (KKTP / KKM), sistem akan memberi tanda warna oranye sebagai penanda siswa memerlukan program remedial.</p>',9)])])}const g=i(r,[["render",t]]);export{d as __pageData,g as default};
